// Vormonat (= der 'abgelaufene Monat', für den gebucht werden soll) berechnen
const monthNames = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const now = new Date();
const prev = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const monat = `${monthNames[prev.getMonth()]} ${prev.getFullYear()}`;

return $input.all()
  .map(i => ({
    json: {
      name: (i.json['MA'] || '').toString().trim(),
      email: (i.json['CROSS_MA.email'] || '').toString().trim(),
      vgEmail: (i.json['CROSS_MA.VG_email'] || '').toString().trim(),
      monat,
    },
  }))
  .filter(i => i.json.name.length > 0 && i.json.email.length > 0);

// Prüft, ob HEUTE der erste Arbeitstag des aktuellen Monats ist.
const now = new Date();
const year = now.getFullYear();
const month = now.getMonth(); // 0-basiert

let firstWorkday = new Date(year, month, 1);
while (firstWorkday.getDay() === 0 || firstWorkday.getDay() === 6) {
  // 0 = Sonntag, 6 = Samstag
  firstWorkday.setDate(firstWorkday.getDate() + 1);
}

const isFirstWorkday = firstWorkday.getDate() === now.getDate()
  && firstWorkday.getMonth() === now.getMonth()
  && firstWorkday.getFullYear() === now.getFullYear();

// Bei 'false' wird ein leeres Item-Array zurückgegeben,
// wodurch die nachfolgenden Nodes ohne Daten ausgeführt werden
// (kein Download, kein Mailversand).
return isFirstWorkday ? $input.all() : [];
